using Endgame.Domain.Tree;
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;

namespace Endgame.Infrastructure.Persistence.Configurations;

internal static class TreeNodeMapping
{
    /// <summary>The columns every level shares. Ids are generated by the domain, never by the database.</summary>
    public static void MapNode<T>(this EntityTypeBuilder<T> builder, string table, NodeLevel level)
        where T : TreeNode
    {
        builder.ToTable(table, t =>
        {
            t.HasCheckConstraint($"ck_{table}_status", Sql.In("status", NodeStatuses.For(level)));
            t.HasCheckConstraint($"ck_{table}_slug", $"slug ~ '{SlugPattern}'");
        });
        builder.HasKey(n => n.Id);
        builder.Property(n => n.Id).HasColumnName("id").ValueGeneratedNever();
        builder.Property(n => n.OrganisationId).HasColumnName("organisation_id").IsRequired();
        builder.Property(n => n.Name).HasColumnName("name").HasMaxLength(TreeNode.MaxNameLength).IsRequired();
        builder.Property(n => n.Slug).HasColumnName("slug").HasMaxLength(SlugRules.MaxLength).IsRequired();
        builder.Property(n => n.Status).HasColumnName("status").HasMaxLength(20).IsRequired();
        builder.Property(n => n.CreatedAt).HasColumnName("created_at").IsRequired();
        builder.Ignore(n => n.Level);
    }

    /// <summary>The slug rule, again in the database: 2-40 characters of one DNS label.</summary>
    public const string SlugPattern = "^(?=.{2,40}$)[a-z0-9]+(-[a-z0-9]+)*$";
}

internal static class Sql
{
    public static string In(string column, IEnumerable<string> values) =>
        $"{column} IN ({string.Join(", ", values.Select(v => $"'{v}'"))})";
}
